const fs = require("fs/promises");
const path = require("path");
const crypto = require("crypto");
const { checkImageEnvelope, writeImageTemps } = require("./image-attachments");
const { readImageSnapshot } = require("./image-file-snapshot");

const MAX_TEXT = 100000;
const MAX_RECORD_BYTES = 2 * 1024 * 1024;
const MAX_STORAGE_BYTES = 100 * 1024 * 1024;
const IMAGE_NAME = /^cc-chat-img-[a-f0-9-]{36}\.(png|jpg|gif|webp)$/;
const KEY = /^[a-f0-9-]{36}$/;
const CLIENT_ID = /^[a-zA-Z0-9_-]{1,80}$/;
const hash = (value) => crypto.createHash("sha256").update(value).digest("hex");

function text(value) {
  if (typeof value !== "string" || value.length > MAX_TEXT)
    throw new Error("Draft text exceeds 100,000 characters or is invalid");
  return value;
}
function validImages(images) {
  return (
    Array.isArray(images) &&
    images.length <= 4 &&
    images.every(
      (i) =>
        IMAGE_NAME.test(i.file) &&
        Number.isSafeInteger(i.size) &&
        i.size > 0 &&
        i.size <= 20 * 1024 * 1024 &&
        /^[a-f0-9]{64}$/.test(i.hash) &&
        ["image/png", "image/jpeg", "image/gif", "image/webp"].includes(i.mime),
    ) &&
    images.reduce((n, i) => n + i.size, 0) <= 20 * 1024 * 1024
  );
}

function validQuestion(q) {
  if (
    !q ||
    !KEY.test(q.id) ||
    !/^[a-f0-9]{64}$/.test(q.digest || "") ||
    typeof q.sessionId !== "string" ||
    typeof q.requestId !== "string" ||
    typeof q.title !== "string" ||
    q.title.length > 1024 ||
    !["draft", "archived"].includes(q.status) ||
    !Array.isArray(q.fields) ||
    q.fields.length > 128 ||
    Buffer.byteLength(JSON.stringify(q)) > 128 * 1024
  )
    throw new Error("Invalid question draft");
  text(q.text);
  const keys = new Set();
  for (const f of q.fields) {
    if (
      !f ||
      typeof f.key !== "string" ||
      f.key.length > 8192 ||
      keys.has(f.key) ||
      (typeof f.value !== "boolean" &&
        (typeof f.value !== "string" || f.value.length > 32768))
    )
      throw new Error("Invalid question draft field");
    keys.add(f.key);
  }
}

/** UI recovery data only. Never grants execution or approval authority. */
class DraftStore {
  constructor(root) {
    this.root = root;
    this.queue = Promise.resolve();
    this.queued = 0;
    this.queuedBytes = 0;
  }

  _serial(action, bytes = 0) {
    if (this.queued >= 64 || this.queuedBytes + bytes > 40 * 1024 * 1024)
      return Promise.reject(
        new Error("Draft storage is busy; keep the editor open and try again"),
      );
    this.queued++;
    this.queuedBytes += bytes;
    const result = this.queue.then(action);
    this.queue = result
      .catch(() => {})
      .finally(() => {
        this.queued--;
        this.queuedBytes -= bytes;
      });
    return result;
  }
  _directory(key) {
    if (!KEY.test(key)) throw new Error("Invalid draft identity");
    return path.join(this.root, key);
  }
  async _read(key) {
    const file = path.join(this._directory(key), "draft.json");
    let handle;
    try {
      const info = await fs.lstat(file);
      if (!info.isFile() || info.size > MAX_RECORD_BYTES)
        throw new Error("Invalid draft record");
      handle = await fs.open(file, "r");
      const data = Buffer.alloc(info.size + 1);
      let n = 0;
      while (n < data.length) {
        const r = await handle.read(data, n, data.length - n, n);
        if (!r.bytesRead) break;
        n += r.bytesRead;
      }
      if (n !== info.size)
        throw new Error("Draft record changed while reading");
      const record = JSON.parse(data.subarray(0, n).toString("utf8"));
      if (
        record.version !== 1 ||
        record.key !== key ||
        !record.composer ||
        !validImages(record.composer.images) ||
        !Array.isArray(record.pending) ||
        record.pending.length > 8 ||
        !Array.isArray(record.questions) ||
        record.questions.length > 16
      )
        throw new Error("Invalid draft record");
      text(record.composer.text);
      for (const q of record.questions) {
        validQuestion(q);
      }
      for (const p of record.pending) {
        text(p.text);
        if (
          !CLIENT_ID.test(p.id) ||
          typeof p.sessionId !== "string" ||
          !validImages(p.images) ||
          !["prepared", "unknown", "rejected", "accepted"].includes(p.status)
        )
          throw new Error("Invalid saved input");
      }
      return record;
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      return {
        version: 1,
        key,
        composer: { text: "", images: [] },
        pending: [],
        questions: [],
      };
    } finally {
      await handle?.close();
    }
  }
  async _quota(extra = 0, creatingKey = null) {
    await fs.mkdir(this.root, { recursive: true, mode: 0o700 });
    const dirs = (await fs.readdir(this.root, { withFileTypes: true })).filter(
      (e) => e.isDirectory() && KEY.test(e.name),
    );
    if (
      dirs.length > 128 ||
      (dirs.length === 128 &&
        creatingKey &&
        !dirs.some((d) => d.name === creatingKey))
    )
      throw new Error("Draft storage has reached its 128 conversation limit");
    let bytes = extra;
    for (const dir of dirs) {
      for (const entry of await fs.readdir(path.join(this.root, dir.name), {
        withFileTypes: true,
      })) {
        if (!entry.isFile()) continue;
        bytes += (await fs.stat(path.join(this.root, dir.name, entry.name)))
          .size;
        if (bytes > MAX_STORAGE_BYTES)
          throw new Error(
            "Draft storage exceeds 100 MiB; discard old saved inputs before adding images",
          );
      }
    }
  }
  async _images(key, images) {
    checkImageEnvelope(images);
    await this._quota(
      images.reduce((n, i) => n + i.data.length * 0.75, 0),
      key,
    );
    const directory = this._directory(key);
    await fs.mkdir(directory, { recursive: true, mode: 0o700 });
    const files = await writeImageTemps(images, { directory });
    const metadata = [];
    try {
      for (const file of files) {
        const data = await readImageSnapshot(file);
        const ext = path.extname(file).slice(1);
        metadata.push({
          file: path.basename(file),
          size: data.length,
          hash: hash(data),
          mime: `image/${ext === "jpg" ? "jpeg" : ext}`,
        });
      }
      return metadata;
    } catch (error) {
      await Promise.allSettled(files.map((file) => fs.unlink(file)));
      throw error;
    }
  }
  async _write(record, assertCurrent = () => {}) {
    assertCurrent();
    const directory = this._directory(record.key);
    if (
      !record.composer.text &&
      !record.composer.images.length &&
      !record.pending.length &&
      !record.questions.length
    ) {
      const names = await fs.readdir(directory).catch(() => []);
      assertCurrent();
      // Removing the manifest commits the empty draft. Finish owned-image
      // cleanup after this point even if the initiating page is replaced.
      await fs.unlink(path.join(directory, "draft.json")).catch((error) => {
        if (error.code !== "ENOENT") throw error;
      });
      for (const name of names) {
        if (IMAGE_NAME.test(name)) await fs.unlink(path.join(directory, name));
      }
      await fs.rmdir(directory).catch(() => {});
      return;
    }
    const data = JSON.stringify(record);
    if (Buffer.byteLength(data) > MAX_RECORD_BYTES)
      throw new Error("Draft metadata exceeds its storage limit");
    const oldSize = await fs.stat(path.join(directory, "draft.json")).then(
      (s) => s.size,
      (error) => {
        if (error.code === "ENOENT") return 0;
        throw error;
      },
    );
    await this._quota(
      Math.max(0, Buffer.byteLength(data) - oldSize),
      record.key,
    );
    await fs.mkdir(directory, { recursive: true, mode: 0o700 });
    const temporary = path.join(directory, `${crypto.randomUUID()}.tmp`);
    try {
      const handle = await fs.open(temporary, "wx", 0o600);
      try {
        await handle.writeFile(data);
        await handle.sync();
      } finally {
        await handle.close();
      }
      assertCurrent();
      await fs.rename(temporary, path.join(directory, "draft.json"));
    } finally {
      await fs.unlink(temporary).catch(() => {});
    }
    // Only delete unreferenced owned images, after publishing the new manifest.
    const keep = new Set(
      [
        ...record.composer.images,
        ...record.pending.flatMap((p) => p.images),
      ].map((i) => i.file),
    );
    for (const name of await fs.readdir(directory).catch(() => [])) {
      if (IMAGE_NAME.test(name) && !keep.has(name))
        await fs.unlink(path.join(directory, name)).catch(() => {});
    }
  }
  async _payload(key, snapshot) {
    const images = [];
    for (const meta of snapshot.images) {
      const file = path.join(this._directory(key), meta.file);
      const data = await readImageSnapshot(file, meta.size);
      if (data.length !== meta.size || hash(data) !== meta.hash)
        throw new Error(
          "Saved attachment is missing or changed; attach it again",
        );
      images.push({
        data: `data:${meta.mime};base64,${data.toString("base64")}`,
        size: data.length,
      });
    }
    return { text: snapshot.text, images };
  }
  save(key, draft, { assertCurrent = () => {} } = {}) {
    if (draft.images !== undefined) checkImageEnvelope(draft.images);
    return this._serial(
      async () => {
        assertCurrent();
        const record = await this._read(key);
        const next = { text: text(draft.text), images: record.composer.images };
        if (draft.images !== undefined)
          next.images = await this._images(key, draft.images);
        record.composer = next;
        record.sessionId = draft.sessionId || record.sessionId || null;
        try {
          await this._write(record, assertCurrent);
        } catch (error) {
          if (draft.images !== undefined)
            await this._removeImages(key, next.images);
          throw error;
        }
      },
      (draft.images || []).reduce((n, i) => n + i.data.length, 0),
    );
  }
  prepare(key, sessionId, id, draft) {
    checkImageEnvelope(draft.images || []);
    return this._serial(
      async () => {
        if (!CLIENT_ID.test(id) || !sessionId)
          throw new Error("Invalid submission identity");
        const record = await this._read(key);
        if (record.pending.some((p) => p.id === id))
          throw new Error(
            "This input already has a saved submission; inspect its acceptance first",
          );
        record.pending = record.pending.filter((p) => p.status !== "accepted");
        if (record.pending.length >= 8)
          throw new Error(
            "Resolve the eight saved submissions before sending more input",
          );
        const input = {
          id,
          sessionId,
          text: text(draft.text),
          images: await this._images(key, draft.images || []),
          status: "prepared",
        };
        record.pending.push(input);
        record.sessionId = sessionId;
        record.composer = { text: "", images: [] };
        try {
          await this._write(record);
        } catch (error) {
          await this._removeImages(key, input.images);
          throw error;
        }
        return {
          ...input,
          paths: input.images.map((i) =>
            path.join(this._directory(key), i.file),
          ),
        };
      },
      (draft.images || []).reduce((n, i) => n + i.data.length, 0),
    );
  }
  async _removeImages(key, images) {
    await Promise.allSettled(
      images
        .filter((i) => IMAGE_NAME.test(i.file))
        .map((i) => fs.unlink(path.join(this._directory(key), i.file))),
    );
  }
  settle(key, id, status, receipt = null) {
    return this._serial(async () => {
      const record = await this._read(key);
      const input = record.pending.find((p) => p.id === id);
      if (!input || input.status === "accepted") return;
      if (!["unknown", "rejected", "accepted"].includes(status))
        throw new Error("Invalid acceptance status");
      if (status === "accepted") {
        if (
          receipt?.sessionId !== input.sessionId ||
          receipt?.clientMessageId !== id ||
          !/^[a-f0-9]{64}$/.test(receipt.eventHash || "") ||
          !/^[a-f0-9]{64}$/.test(receipt.inputDigest || "")
        )
          throw new Error("Input receipt does not match saved submission");
        input.receipt = receipt;
        input.images = [];
      }
      input.status = status;
      await this._write(record);
    });
  }
  view(key, { includeComposer = true } = {}) {
    return this._serial(async () => {
      const record = await this._read(key);
      let composer;
      try {
        if (includeComposer)
          composer = await this._payload(key, record.composer);
      } catch (error) {
        composer = {
          text: record.composer.text,
          images: [],
          missingImages: true,
          error: error.message,
        };
      }
      return {
        composer,
        pending: record.pending.map(({ images, ...p }) => ({
          ...p,
          imageCount: images.length,
        })),
        questions: record.questions,
      };
    });
  }
  recover(key, id) {
    return this._serial(async () => {
      const record = await this._read(key);
      const input = record.pending.find((p) => p.id === id);
      if (!input || input.status === "accepted")
        throw new Error("Accepted input cannot be restored for resubmission");
      return this._payload(key, input); // explicit editable copy; never sends it
    });
  }
  discard(key, id) {
    return this._serial(async () => {
      const record = await this._read(key);
      record.pending = record.pending.filter((p) => p.id !== id);
      await this._write(record);
    });
  }
  saveQuestion(key, question) {
    validQuestion(question);
    return this._serial(async () => {
      if (
        !KEY.test(question.id) ||
        !/^[a-f0-9]{64}$/.test(question.digest || "") ||
        Buffer.byteLength(JSON.stringify(question)) > 128 * 1024
      )
        throw new Error("Invalid or oversized question draft");
      const record = await this._read(key);
      const old = record.questions.find((q) => q.id === question.id);
      if (old && old.digest !== question.digest)
        throw new Error("Question draft identity changed");
      if (!old && record.questions.length >= 16)
        throw new Error(
          "Discard an old question draft before saving more than 16 questions",
        );
      record.questions = record.questions.filter((q) => q.id !== question.id);
      record.questions.push({
        ...question,
        status: old?.status === "archived" ? "archived" : question.status,
      });
      record.sessionId ||= question.sessionId;
      await this._write(record);
    });
  }
  archiveQuestion(key, id, digest = null) {
    return this._serial(async () => {
      const record = await this._read(key);
      const found = record.questions.filter(
        (q) => q.id === id || (digest && q.digest === digest),
      );
      if (found.length) {
        for (const q of found) q.status = "archived";
        await this._write(record);
      }
    });
  }
  discardQuestion(key, id) {
    return this._serial(async () => {
      const record = await this._read(key);
      record.questions = record.questions.filter((q) => q.id !== id);
      await this._write(record);
    });
  }
  list() {
    return this._serial(async () => {
      const entries = await fs
        .readdir(this.root, { withFileTypes: true })
        .catch((error) => {
          if (error.code === "ENOENT") return [];
          throw error;
        });
      const result = [];
      for (const entry of entries
        .filter((e) => e.isDirectory() && KEY.test(e.name))
        .slice(0, 128)) {
        const record = await this._read(entry.name);
        if (
          !record.composer.text &&
          !record.composer.images.length &&
          !record.pending.length &&
          !record.questions.length
        )
          continue;
        result.push({
          key: entry.name,
          sessionId: record.sessionId || record.pending[0]?.sessionId || null,
          label: (
            record.composer.text ||
            record.pending[0]?.text ||
            record.questions[0]?.title ||
            "Image draft"
          ).slice(0, 100),
          description: `${record.pending.length} saved submissions`,
        });
      }
      return result;
    });
  }
}
module.exports = { DraftStore };

import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { DraftStore } from "../../../vscode-extension/src/chat/draft-store.js";
import { ChatViewProvider } from "../../../vscode-extension/src/chat/chat-view.js";
import { buildChatHtml } from "../../../vscode-extension/src/chat/chat-html.js";
import { Window } from "happy-dom";

const roots = [];
const providers = [];
afterEach(async () => {
  for (const p of providers.splice(0)) p.dispose();
  for (const root of roots.splice(0))
    await fs.rm(root, { recursive: true, force: true });
});
async function storage() {
  const root = await fs.mkdtemp(path.join(tmpdir(), "cc-draft-"));
  roots.push(root);
  return root;
}
const image = {
  data: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==",
};
function receipt(sessionId, clientMessageId) {
  return {
    sessionId,
    clientMessageId,
    inputDigest: "a".repeat(64),
    eventHash: "b".repeat(64),
  };
}

describe("durable composer storage", () => {
  it("commits an empty manifest before image cleanup and completes cleanup after page replacement", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "image draft", images: [image] });
    let current = true;
    let cleanedImage = false;
    const unlink = fs.unlink.bind(fs);
    const spy = vi.spyOn(fs, "unlink").mockImplementation(async (file) => {
      if (String(file).endsWith(".png")) {
        await expect(
          fs.stat(path.join(root, key, "draft.json")),
        ).rejects.toMatchObject({ code: "ENOENT" });
        current = false;
        cleanedImage = true;
      }
      return unlink(file);
    });
    try {
      await store.save(
        key,
        { text: "", images: [] },
        {
          assertCurrent: () => {
            if (!current) throw new Error("inactive page");
          },
        },
      );
      expect(cleanedImage).toBe(true);
      expect(await store.list()).toEqual([]);
      await expect(fs.stat(path.join(root, key))).rejects.toMatchObject({
        code: "ENOENT",
      });
    } finally {
      spy.mockRestore();
    }
  });
  it("rechecks page lifetime before rename and removes an abandoned temporary manifest", async () => {
    const root = await storage();
    const store = new DraftStore(root);
    const key = randomUUID();
    await store.save(key, { text: "original" });
    const before = await fs.readFile(path.join(root, key, "draft.json"));
    let release;
    let paused = false;
    let current = true;
    const gate = new Promise((done) => {
      release = done;
    });
    const quota = store._quota.bind(store);
    const spy = vi
      .spyOn(store, "_quota")
      .mockImplementation(async (...args) => {
        await quota(...args);
        paused = true;
        await gate;
      });
    const saving = store.save(
      key,
      { text: "obsolete" },
      {
        assertCurrent: () => {
          if (!current) throw new Error("inactive page");
        },
      },
    );
    const rejection = expect(saving).rejects.toThrow("inactive page");
    try {
      await until(() => paused);
      current = false;
      release();
      await rejection;
      expect(await fs.readFile(path.join(root, key, "draft.json"))).toEqual(
        before,
      );
      expect(await fs.readdir(path.join(root, key))).toEqual(["draft.json"]);
    } finally {
      release();
      spy.mockRestore();
      await saving.catch(() => {});
    }
  });
  it("recovers text and image snapshots in a fresh store, with no image data in metadata", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "draft 中文", images: [image] });
    await store.save(key, { text: "edited 中文" });
    const restored = await new DraftStore(root).view(key);
    expect(restored.composer.text).toBe("edited 中文");
    expect(restored.composer.images[0].data).toBe(image.data);
    const metadata = await fs.readFile(
      path.join(root, key, "draft.json"),
      "utf8",
    );
    expect(metadata).not.toContain("base64");
  });
  it("saves a submitted snapshot before clearing the composer, and retains unknown sends", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "old", images: [image] });
    const prepared = await store.prepare(key, "session-1", "input-1", {
      text: "submitted",
      images: [image],
    });
    expect((await store.view(key)).composer.text).toBe("");
    await store.settle(key, "input-1", "unknown");
    expect(
      (await new DraftStore(root).recover(key, "input-1")).images[0].data,
    ).toBe(image.data);
    await expect(
      store.settle(key, "input-1", "accepted", receipt("other", "input-1")),
    ).rejects.toThrow("match");
    await store.settle(
      key,
      "input-1",
      "accepted",
      receipt("session-1", "input-1"),
    );
    await expect(store.recover(key, "input-1")).rejects.toThrow("Accepted");
    await expect(fs.stat(prepared.paths[0])).rejects.toMatchObject({
      code: "ENOENT",
    });
  });
  it("does not silently omit missing attachments or accept a tampered snapshot", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "keep text", images: [image] });
    const record = JSON.parse(
      await fs.readFile(path.join(root, key, "draft.json"), "utf8"),
    );
    await fs.unlink(path.join(root, key, record.composer.images[0].file));
    expect((await store.view(key)).composer).toMatchObject({
      text: "keep text",
      missingImages: true,
    });
    record.composer.images[0].file = "../../secret.png";
    await fs.writeFile(
      path.join(root, key, "draft.json"),
      JSON.stringify(record),
    );
    await expect(store.view(key)).rejects.toThrow("Invalid draft");
  });
  it("retains the old draft and cleans new attachments when publishing fails", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "original", images: [image] });
    const before = (await fs.readdir(path.join(root, key))).sort();
    const rename = vi
      .spyOn(fs, "rename")
      .mockRejectedValueOnce(new Error("ENOSPC"));
    try {
      await expect(
        store.save(key, { text: "new", images: [image] }),
      ).rejects.toThrow("ENOSPC");
    } finally {
      rename.mockRestore();
    }
    expect((await store.view(key)).composer.text).toBe("original");
    expect((await fs.readdir(path.join(root, key))).sort()).toEqual(before);
  });
  it("bounds pending records and does not evict unknown inputs", async () => {
    const store = new DraftStore(await storage());
    const key = randomUUID();
    for (let i = 0; i < 8; i++)
      await store.prepare(key, "session", `input-${i}`, {
        text: `${i}`,
        images: [],
      });
    await expect(
      store.prepare(key, "session", "input-9", { text: "9" }),
    ).rejects.toThrow("eight");
    expect((await store.view(key)).pending).toHaveLength(8);
    await expect(store.save(key, { text: "a".repeat(100001) })).rejects.toThrow(
      "100,000",
    );
  });

  it("serializes rapid edits without rewriting attachment snapshots", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "first", images: [image] });
    const before = (await fs.readdir(path.join(root, key))).filter((n) =>
      n.endsWith(".png"),
    );
    await Promise.all(
      Array.from({ length: 20 }, (_, i) =>
        store.save(key, { text: `edit-${i}` }),
      ),
    );
    expect((await store.view(key)).composer.text).toBe("edit-19");
    expect(
      (await fs.readdir(path.join(root, key))).filter((n) =>
        n.endsWith(".png"),
      ),
    ).toEqual(before);
    await store.save(key, { text: "", images: [] });
    expect(await store.list()).toEqual([]);
  });
});

function host(root, state = new Map(), deps = {}) {
  const messages = [];
  const sessions = [];
  const provider = new ChatViewProvider(
    {
      workspace: {
        workspaceFolders: [],
        getConfiguration: () => ({ get: () => undefined }),
      },
      commands: { executeCommand() {} },
      window: {},
    },
    {
      storagePath: root,
      state: {
        get: (k) => state.get(k),
        update: async (k, v) => state.set(k, v),
      },
      deps: {
        resolveChatLlm: () => ({}),
        loadTranscriptPage: async () => {
          throw new Error("no transcript");
        },
        createSession: (cfg) => {
          const session = {
            cfg,
            running: true,
            sent: [],
            sendEvent: vi.fn((e) => {
              session.sent.push(e);
              return true;
            }),
            stop() {
              this.running = false;
            },
          };
          sessions.push(session);
          return session;
        },
        ...deps,
      },
    },
  );
  providers.push(provider);
  provider.view = {
    webview: {
      postMessage: (m) => {
        messages.push(m);
        return Promise.resolve(true);
      },
    },
  };
  provider._activeConv();
  provider._postTabs();
  return { provider, sessions, messages, state };
}
async function until(condition) {
  await vi.waitFor(() => expect(condition()).toBeTruthy(), {
    timeout: 4000,
    interval: 5,
  });
}
function init(h, version = 1) {
  const conv = h.provider._activeConv();
  h.sessions.at(-1).cfg.onEvent({
    type: "system",
    subtype: "init",
    session_id: conv.sessionId,
    input_receipts: { version },
  });
}

describe("host durable input lifecycle", () => {
  it("rejects a replaced page's saves and drops delayed image writes before publication", async () => {
    const h = host(await storage());
    h.provider.vscode.l10n = { t: (value) => value };
    h.provider._buildChatHtml(h.provider.view);
    h.provider._handleMessage({
      type: "ready",
      webviewNonce: h.provider._draftWebviewNonce,
      webviewInstance: randomUUID(),
    });
    const oldInstance = h.provider._draftWebviewInstance;
    const conv = h.provider._activeConv();
    const key = h.provider._draftKey(conv);
    const request = {
      type: "draftUpdate",
      convId: conv.id,
      draftKey: key,
      webviewInstance: oldInstance,
      revision: 5,
      text: "old page",
      images: [image],
    };
    const store = h.provider._draftStore;
    const original = store._images.bind(store);
    let release;
    let paused = false;
    const gate = new Promise((done) => {
      release = done;
    });
    const spy = vi
      .spyOn(store, "_images")
      .mockImplementation(async (...args) => {
        const metadata = await original(...args);
        paused = true;
        await gate;
        return metadata;
      });
    const oldSave = h.provider._handleMessage(request);
    try {
      await until(() => paused);
      // Reload Webviews executes the same cached HTML, retaining its nonce.
      h.provider._handleMessage({
        type: "ready",
        webviewNonce: h.provider._draftWebviewNonce,
        webviewInstance: randomUUID(),
      });
      const currentInstance = h.provider._draftWebviewInstance;
      expect(currentInstance).not.toBe(oldInstance);
      expect(
        h.provider._handleMessage({
          type: "protocol",
          webviewNonce: h.provider._draftWebviewNonce,
          webviewInstance: oldInstance,
        }),
      ).toBe(false);
      expect(h.provider._draftWebviewInstance).toBe(currentInstance);
      const currentSave = h.provider._handleMessage({
        ...request,
        webviewInstance: currentInstance,
        revision: 1,
        text: "new page",
        images: [],
      });
      release();
      await Promise.all([oldSave, currentSave]);
      await h.provider._handleMessage(request);
      expect((await store.view(key)).composer).toEqual({
        text: "new page",
        images: [],
      });
      expect(
        (await fs.readdir(path.join(store.root, key))).filter((name) =>
          name.endsWith(".png"),
        ),
      ).toEqual([]);
      expect(h.messages.filter((m) => m.kind === "draftSaved")).toEqual([
        expect.objectContaining({
          webviewInstance: currentInstance,
          revision: 1,
        }),
      ]);
      expect(
        h.messages
          .filter((m) => m.kind === "draftSaveError")
          .every((m) => m.webviewInstance === oldInstance),
      ).toBe(true);
    } finally {
      release();
      spy.mockRestore();
      await oldSave;
    }
  });
  it.each(["prepare", "init", "unknown", "session-stop"])(
    "cancels an undispatched saved input during %s without losing its recovery record",
    async (stage) => {
      const h = host(await storage());
      const conv = h.provider._activeConv();
      let release;
      let paused = false;
      const gate = new Promise((done) => {
        release = done;
      });
      const method = stage === "unknown" ? "settle" : "prepare";
      const original = h.provider._draftStore[method].bind(
        h.provider._draftStore,
      );
      const spy = vi
        .spyOn(h.provider._draftStore, method)
        .mockImplementation(async (...args) => {
          const result = await original(...args);
          if (
            stage !== "init" &&
            (method === "prepare" || args[2] === "unknown")
          ) {
            paused = true;
            await gate;
          }
          return result;
        });
      const sending = h.provider._handleMessage({
        type: "send",
        text: "cancelled question",
        clientMessageId: "cancelled-1",
      });
      try {
        if (stage === "init" || stage === "unknown") {
          await until(() => h.sessions.length === 1);
          if (stage === "unknown") init(h);
          else await until(() => conv.inputInitWaiters?.size === 1);
        }
        if (stage !== "init") await until(() => paused);
        if (stage === "session-stop") h.provider._stopSession(conv);
        else expect(h.provider._interruptConversation(conv)).toBe(true);
        release();
        expect(await sending).toBe(false);
        expect(
          h.sessions.flatMap((s) => s.sent).filter((e) => e.type === "user"),
        ).toEqual([]);
        expect(
          (await h.provider._draftStore.view(conv.draftKey)).pending[0],
        ).toMatchObject({
          id: "cancelled-1",
          status: "rejected",
          text: "cancelled question",
        });
        expect(
          h.messages.find((m) => m.kind === "submissionFailed").text,
        ).toContain("stopped");
      } finally {
        release();
        await sending;
        spy.mockRestore();
      }
    },
  );

  it("does not start the agent when the submission cannot be saved", async () => {
    const h = host(await storage());
    const conv = h.provider._activeConv();
    await h.provider._draftStore.save(conv.draftKey, {
      text: "retained draft",
    });
    const prepare = vi
      .spyOn(h.provider._draftStore, "prepare")
      .mockRejectedValueOnce(new Error("disk full"));
    await h.provider._handleMessage({
      type: "send",
      text: "retained draft",
      clientMessageId: "input-1",
    });
    expect(h.sessions).toEqual([]);
    expect(
      (await h.provider._draftStore.view(conv.draftKey)).composer.text,
    ).toBe("retained draft");
    expect(h.messages.find((m) => m.kind === "submissionFailed")).toMatchObject(
      { stored: false },
    );
    prepare.mockRestore();
  });
  it("waits for init, persists UNKNOWN before writing and settles only a correlated ACK", async () => {
    const h = host(await storage());
    const conv = h.provider._activeConv();
    const sending = h.provider._handleMessage({
      type: "send",
      text: "question",
      clientMessageId: "input-1",
    });
    await until(() => h.sessions.length === 1);
    expect(h.sessions[0].sent).toEqual([]);
    init(h);
    await sending;
    expect(h.sessions[0].sent[0]).toMatchObject({
      type: "user",
      client_message_id: "input-1",
      text: "question",
    });
    expect(
      (await h.provider._draftStore.view(conv.draftKey)).pending[0].status,
    ).toBe("unknown");
    expect(h.messages.some((m) => m.kind === "sendAccepted")).toBe(false);
    h.sessions[0].cfg.onEvent({
      type: "system",
      subtype: "input_accepted",
      session_id: "wrong",
      client_message_id: "input-1",
      receipt: receipt("wrong", "input-1"),
    });
    expect(
      (await h.provider._draftStore.view(conv.draftKey)).pending[0].status,
    ).toBe("unknown");
    h.sessions[0].cfg.onEvent({
      type: "system",
      subtype: "input_accepted",
      session_id: conv.sessionId,
      client_message_id: "input-1",
      receipt: receipt(conv.sessionId, "input-1"),
    });
    expect(
      (await h.provider._draftStore.view(conv.draftKey)).pending[0].status,
    ).toBe("accepted");
  });
  it("reloads a stable draft identity and reconciles read-only without starting a session", async () => {
    const root = await storage();
    const h = host(root);
    const conv = h.provider._activeConv();
    const sending = h.provider._handleMessage({
      type: "send",
      text: "lost ACK",
      clientMessageId: "input-1",
    });
    await until(() => h.sessions.length);
    init(h);
    await sending;
    await h.provider._draftStore.save(conv.draftKey, {
      text: "next draft",
      images: [image],
    });
    h.provider.dispose();
    let finishLookup;
    const lookup = vi.fn(
      (sid, id) =>
        new Promise((resolve) => {
          finishLookup = () =>
            resolve({ accepted: true, receipt: receipt(sid, id) });
        }),
    );
    const restored = host(root, h.state, { readInputReceipt: lookup });
    const next = restored.provider._activeConv();
    expect(next.draftKey).toBe(conv.draftKey);
    const recovering = restored.provider._restoreDraft(next, {
      reconcile: true,
    });
    await until(() => finishLookup);
    expect(restored.sessions).toEqual([]);
    expect(lookup).toHaveBeenCalledWith(conv.sessionId, "input-1");
    const snapshot = restored.messages.find((m) => m.kind === "draftSnapshot");
    expect(snapshot.composer.text).toBe("next draft");
    expect(snapshot.composer.images[0].data).toBe(image.data);
    expect(snapshot.pending[0].status).toBe("unknown");
    finishLookup();
    await recovering;
    expect(
      restored.messages.filter((m) => m.kind === "draftSnapshot").at(-1)
        .pending[0].status,
    ).toBe("accepted");
  });
  it("keeps legacy CLI and failed pipe writes unknown and recoverable", async () => {
    const h = host(await storage());
    const conv = h.provider._activeConv();
    const sending = h.provider._handleMessage({
      type: "send",
      text: "retain me",
      clientMessageId: "input-1",
    });
    await until(() => h.sessions.length);
    h.sessions[0].sendEvent.mockReturnValue(false);
    init(h, 0);
    await sending;
    expect(
      (await h.provider._draftStore.view(conv.draftKey)).pending[0].status,
    ).toBe("unknown");
    expect(
      (await h.provider._draftStore.recover(conv.draftKey, "input-1")).text,
    ).toBe("retain me");
  });
  it("does not dispatch a saved input after its conversation is reset", async () => {
    const h = host(await storage());
    const conv = h.provider._activeConv();
    const sending = h.provider._handleMessage({
      type: "send",
      text: "old",
      clientMessageId: "input-1",
    });
    await until(() => h.sessions.length);
    const oldKey = conv.draftKey;
    h.provider._handleMessage({ type: "new" });
    await sending;
    expect(h.sessions[0].sent).toEqual([]);
    expect(conv.draftKey).not.toBe(oldKey);
    expect((await h.provider._draftStore.view(oldKey)).pending[0].status).toBe(
      "rejected",
    );
  });

  it("keeps closed drafts discoverable and reopens the same draft identity", async () => {
    const h = host(await storage());
    const conv = h.provider._activeConv();
    await h.provider._draftStore.save(conv.draftKey, { text: "closed draft" });
    h.provider._webviewReady = true;
    h.provider._handleMessage({ type: "closeTab", id: conv.id });
    expect((await h.provider._draftStore.list()).map((d) => d.label)).toContain(
      "closed draft",
    );
    h.provider.reopenClosedSession();
    expect(h.provider._activeConv().draftKey).toBe(conv.draftKey);
    expect(h.sessions).toEqual([]);
  });
});

function webview(backup, { withoutRandomUUID = false } = {}) {
  const window = new Window({
    settings: {
      enableJavaScriptEvaluation: true,
      disableCSSFileLoading: true,
      disableJavaScriptFileLoading: true,
    },
  });
  const posted = [];
  // This harness tests ACK/page routing; actual codecs run in the separate
  // Chromium journey. Keep completion explicit so ACK alone cannot show img.
  const decoders = [];
  window.HTMLCanvasElement.prototype.getContext = () => ({
    clearRect() {},
    drawImage() {},
  });
  window.Worker = class {
    constructor() {
      decoders.push(this);
    }
    postMessage(images) {
      this.images = images;
    }
    terminate() {
      this.terminated = true;
    }
  };
  if (withoutRandomUUID)
    Object.defineProperty(window, "crypto", {
      value: {
        getRandomValues: window.crypto.getRandomValues.bind(window.crypto),
      },
    });
  let state = backup || {};
  window.acquireVsCodeApi = () => ({
    postMessage: (m) => posted.push(m),
    getState: () => state,
    setState: (s) => {
      state = s;
    },
  });
  window.document.write(
    buildChatHtml({ nonce: "n", cspSource: "vscode-resource:" }),
  );
  const emit = (data) =>
    window.dispatchEvent(new window.MessageEvent("message", { data }));
  const keys = {
    a: "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa",
    b: "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb",
  };
  const tabs = (id) =>
    emit({
      kind: "tabs",
      activeId: id,
      tabs: Object.keys(keys).map((id) => ({
        id,
        title: id,
        draftKey: keys[id],
        draftStorage: true,
      })),
    });
  return {
    window,
    posted,
    decoders,
    emit,
    keys,
    tabs,
    input: window.document.getElementById("input"),
    state: () => state,
    page: posted.find((m) => m.type === "ready"),
  };
}
describe("composer recovery in the generated Webview", () => {
  it("initializes the page and draft handshake without the secure-context randomUUID API", async () => {
    const ui = webview(undefined, { withoutRandomUUID: true });
    try {
      expect(ui.page.webviewInstance).toMatch(
        /^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/,
      );
      ui.emit({ kind: "thinking", text: "reasoning is visible" });
      expect(
        ui.window.document.querySelector("details.thinking").textContent,
      ).toContain("reasoning is visible");
    } finally {
      await ui.window.happyDOM.abort();
    }
  });
  it("binds recovery actions to the current page and keeps their errors visible", async () => {
    const ui = webview();
    try {
      ui.tabs("a");
      ui.emit({
        kind: "draftSnapshot",
        convId: "a",
        draftKey: ui.keys.a,
        pending: [{ id: "input-1", status: "unknown", text: "saved input" }],
      });
      for (const [label, type] of [
        ["Check acceptance", "draftReconcile"],
        ["Copy to composer", "draftRecover"],
        ["Discard saved input", "draftDiscard"],
      ]) {
        [...ui.window.document.querySelectorAll("button")]
          .find((button) => button.textContent === label)
          .click();
