import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { DraftStore } from "../src/chat/draft-store.js";

const roots = [];
afterEach(async () => {
  for (const root of roots.splice(0))
    await fs.rm(root, { recursive: true, force: true });
});
async function storage() {
  const root = await fs.mkdtemp(path.join(tmpdir(), "cc-draft-v25-"));
  roots.push(root);
  return root;
}
const image = {
  data: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==",
};

describe("draft write failure retains the old record", () => {
  it("commits a composer save durably (positive control)", async () => {
    const store = new DraftStore(await storage());
    const key = randomUUID();
    await store.save(key, { text: "original" });
    await store.save(key, { text: "revised" });
    expect((await store.view(key)).composer.text).toBe("revised");
    expect((await store.view(key)).composer.images).toEqual([]);
  });

  it("restores the prior draft after an atomic save write failure", async () => {
    const store = new DraftStore(await storage());
    const key = randomUUID();
    await store.save(key, { text: "original", images: [image] });
    const before = (await fs.readdir(path.join(store.root, key))).sort();
    const rename = vi
      .spyOn(fs, "rename")
      .mockRejectedValueOnce(new Error("ENOSPC"));
    try {
      await expect(
        store.save(key, { text: "new text", images: [image] }),
      ).rejects.toThrow("ENOSPC");
    } finally {
      rename.mockRestore();
    }
    const restored = await new DraftStore(store.root).view(key);
    expect(restored.composer.text).toBe("original");
    expect(restored.composer.images[0].data).toBe(image.data);
    expect((await fs.readdir(path.join(store.root, key))).sort()).toEqual(
      before,
    );
  });

  it("clears the composer only after a prepared submission is durably written", async () => {
    const store = new DraftStore(await storage());
    const key = randomUUID();
    await store.save(key, { text: "about to send" });
    await store.prepare(key, "session-1", "input-1", {
      text: "sent",
      images: [],
    });
    const view = await store.view(key);
    expect(view.composer.text).toBe("");
    expect(view.pending[0]).toMatchObject({
      id: "input-1",
      status: "prepared",
    });
  });

  it("does not clear the composer early when the submission write fails", async () => {
    const store = new DraftStore(await storage());
    const key = randomUUID();
    await store.save(key, { text: "draft kept on failure" });
    const rename = vi
      .spyOn(fs, "rename")
      .mockRejectedValueOnce(new Error("ENOSPC"));
    try {
      await expect(
        store.prepare(key, "session-1", "input-1", {
          text: "sent",
          images: [image],
        }),
      ).rejects.toThrow("ENOSPC");
    } finally {
      rename.mockRestore();
    }
    const view = await store.view(key);
    expect(view.composer.text).toBe("draft kept on failure");
    expect(view.pending).toEqual([]);
    expect(
      (await fs.readdir(path.join(store.root, key))).filter((n) =>
        n.endsWith(".png"),
      ),
    ).toEqual([]);
  });
});

