    {
      workspace: {
        workspaceFolders: [],
        getConfiguration: () => ({ get: () => undefined }),
      },
      commands: { executeCommand() {} },
      window: {},
    },
    {
      storagePath: root,
      state: {
        get: (k) => state.get(k),
        update: async (k, v) => state.set(k, v),
      },
      deps: {
        resolveChatLlm: () => ({}),
        loadTranscriptPage: async () => {
          throw new Error("no transcript");
        },
        createSession: (cfg) => {
          const session = {
            cfg,
            running: true,
            sent: [],
            sendEvent: vi.fn((e) => {
              session.sent.push(e);
              return true;
            }),
            stop() {
              this.running = false;
            },
          };
          sessions.push(session);
          return session;
        },
        ...deps,
      },
    },
  );
